import { useState } from 'react';
import { useNavigate } from 'react-router-dom';

const useSignUpHandler = (handleSignUp) => {
    const [name, setName] = useState('');
    const [mobile, setMobile] = useState('');
    const [email, setEmail] = useState('');
    const [passwords, setPassword] = useState('');
    const [errorMessage, setErrorMessage] = useState('');
    const [successMessage, setSuccessMessage] = useState('');
    
    const navigate = useNavigate(); // Initialize useNavigate

    const handleSignUpFormSubmit = async (e) => {
        e.preventDefault();

        // Validation
        if (!name.trim()) {
            setErrorMessage('Name is required.');
            setTimeout(() => setErrorMessage(''), 5000);
            return;
        }

        const mobileRegex = /^\d{10}$/;
        if (!mobileRegex.test(mobile)) {
            setErrorMessage('Mobile must be a 10-digit number.');
            setTimeout(() => setErrorMessage(''), 5000);
            return;
        }

        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(email)) {
            setErrorMessage('Invalid email address.');
            setTimeout(() => setErrorMessage(''), 5000);
            return;
        }

        const passwordRegex = /^\d{4}$/;
        if (!passwordRegex.test(passwords)) {
            setErrorMessage('Password must be a 4-digit number.');
            setTimeout(() => setErrorMessage(''), 5000);
            return;
        }

        try {
            const response = await fetch('/DataLogger/CheckSingUpCredentials', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    name,
                    mobile,
                    email,
                    password: parseInt(passwords, 10),
                }),
            });

            if (response.ok) {
                // const data = await response.json();
                setSuccessMessage('Sign-up successful!');
                setErrorMessage('');
                // alert(`Sign-up successful: ${data.message}`); // Show alert with returned message
                // handleSignUp({ data }); // Pass data for further action
                navigate('/SignIn'); // Redirect to the login page
            } else {
                const responseData = await response.json();
                setErrorMessage(`Sign-up failed: ${responseData.message}`);
                setSuccessMessage('');
                setTimeout(() => setErrorMessage(''), 5000);
            }
        } catch (error) {
            setErrorMessage('An error occurred during sign-up. Please try again later.');
            setSuccessMessage('');
            setTimeout(() => setErrorMessage(''), 5000);
        }
    };

    return {
        name, setName, mobile, setMobile, email, setEmail, passwords, setPassword, errorMessage, successMessage, handleSignUpFormSubmit,
    };
};

export default useSignUpHandler;
