import React, { useState } from 'react';
import { Routes, Route, Navigate, useNavigate } from 'react-router-dom';
import SignIn from './pages/SignIn';
import SignUp from './pages/SignUp';
import Dashboard from './pages/Dashboard';
import ChannelHistory from './pages/ChannelHistory';

// Import the SearchResultsProvider
import { SearchResultsProvider } from './js/SearchResultsContext';

function App() {
  const storedUser = JSON.parse(sessionStorage.getItem('User'));
  const [loggedIn, setLoggedIn] = useState(!!storedUser);
  const [userInfo, setUserInfo] = useState(storedUser || {});
  const navigate = useNavigate(); 

  // Handle SignIn
  const handleSignIn = (data) => {
    if (data && data.data) {
      setUserInfo(data.data);
      setLoggedIn(true);
      sessionStorage.setItem('User', JSON.stringify(data.data)); // Store in sessionStorage
      navigate('/Dashboard'); // Directly navigate to the dashboard after SignIn
    } else {
      console.error("SignIn response does not contain valid data");
    }
  };

  // Handle logout
  const handleLogout = () => {
    setLoggedIn(false);
    setUserInfo({});
    sessionStorage.removeItem('User');
    navigate('/'); // Redirect to SignIn page on logout
  };

  return (
    <SearchResultsProvider>
      <Routes>
        <Route
          path="/"
          element={loggedIn ? <Navigate to="/Dashboard" /> : <Navigate to="/SignIn" />}
        />
        <Route
          path="/SignIn"
          element={<SignIn handleSignIn={handleSignIn} />}
        />
        <Route
          path="/Dashboard"
          element={
            loggedIn ? (
              <Dashboard userInfo={userInfo} handleLogout={handleLogout} />
            ) : (
              <Navigate to="/SignIn" />
            )
          }
        />
        <Route
          path="/ChannelHistory"
          element={
            loggedIn ? (
              <ChannelHistory userInfo={userInfo} handleLogout={handleLogout} />
            ) : (
              <Navigate to="/SignIn" />
            )
          }
        />
        <Route
          path="/SignUp"
          element={
            loggedIn ? (
              <SignUp userInfo={userInfo} handleLogout={handleLogout} />
            ) : (
              <Navigate to="/SignIn" />
            )
          }
        />
      </Routes>
    </SearchResultsProvider>
  );
}

// Ensure BrowserRouter is wrapping App in the main index.js or App.js

export default App;
