import { useState } from 'react';

const useSignInHandler = (handleSignIn) => {
    const [email, setEmail] = useState('');
    const [passwords, setPassword] = useState('');
    const [errorMessage, setErrorMessage] = useState('');
    const [successMessage, setSuccessMessage] = useState('');

    const handleSignInFormSubmit = async (e) => {
        e.preventDefault();

        // Password validation
        const passwordRegex = /^\d{4}$/;
        if (!passwords || !passwordRegex.test(passwords)) {
            setErrorMessage('Password must be a 4-digit number.');
            setTimeout(() => {
                setErrorMessage('');
            }, 5000);
            return;
        }

        try {
            const parsedPassword = parseInt(passwords, 10);
            const response = await fetch('/DataLogger/CheckSignInCredentials', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ email, password: parsedPassword }),
            });

            if (response.ok) {
                const data = await response.json();
                setSuccessMessage('SignIn successful!');
                setErrorMessage('');
                handleSignIn({ data });
                console.log(data); // Use `data` for further actions like saving token or redirecting
            } else {
                const responseData = await response.json();
                setErrorMessage(`SignIn failed, ${responseData.message}`);
                setSuccessMessage('');
                setTimeout(() => {
                    setErrorMessage('');
                }, 5000);
            }
        } catch (error) {
            setErrorMessage('An error occurred during SignIn. Please try again later.');
            setSuccessMessage('');
            setTimeout(() => {
                setErrorMessage('');
            }, 5000);
        }
    };

    return { email, setEmail, passwords, setPassword, errorMessage, successMessage, handleSignInFormSubmit };
};

export default useSignInHandler;
