import React, { createContext, useState, useEffect, useContext } from 'react';

// Create context
const SearchResultsContext = createContext();

// Custom hook to use the context
export const useSearchResults = () => {
  return useContext(SearchResultsContext);
};

// Provider component to wrap the app and manage state
export const SearchResultsProvider = ({ children }) => {
  const [searchResults, setSearchResults] = useState(null);
  // const userEmail = searchResults?.userInfo?.data?.email; // Safe access with optional chaining
  // console.log(userEmail); 

  // Load session data on component mount
  useEffect(() => {
    const savedResults = sessionStorage.getItem('searchResults');
    if (savedResults) {
      setSearchResults(JSON.parse(savedResults));
    }
  }, []);

  // Update search results in state and session storage
  const updateSearchResults = (results) => {
    // console.log("Updating search results with:", results);
    setSearchResults(results);
    sessionStorage.setItem('searchResults', JSON.stringify(results));
  };

  return (
    <SearchResultsContext.Provider value={{ searchResults, updateSearchResults }}>
      {children}
    </SearchResultsContext.Provider>
  );
};
