import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import { useHeaderLogic } from '../js/HeaderLogic';

const Header = ({ userInfo, handleLogout }) => {
    const location = useLocation(); // React Router's useLocation hook

    // Determine the page title based on the pathname
    const pageTitle = () => {
        switch (location.pathname) {
        case '/Dashboard':
            return 'Dashboard';
        case '/ChannelHistory':
            return 'Channel History';
        default:
            return 'Page Not Found';
        }
    };

    const {
        toggleSidebar,
        handleLogoutWithConfirmation,
        handleSearch,
        searchTerm,
        setSearchTerm,
    } = useHeaderLogic(userInfo);
    
return (
    <nav className="navbar navbar-main navbar-expand-lg px-0 mx-4 shadow-none border-radius-xl position-sticky blur shadow-blurleft-auto top-1 z-index-sticky" style={{paddingTop:'10px'}} id="navbarBlur" navbar-scroll="true">
        <div className="container-fluid py-1 px-3">
            <nav aria-label="breadcrumb">
                <ol className="breadcrumb bg-transparent mb-0 pb-0 pt-1 px-0 me-sm-6 me-5">
                    <li className="breadcrumb-item text-sm"><Link className="opacity-5 text-dark" href="#">Pages</Link></li>
                    <li className="breadcrumb-item text-sm text-dark active" aria-current="page">{pageTitle()}</li>
                </ol>
                <h6 className="font-weight-bolder mb-0">{userInfo.data.email}</h6>
            </nav>
            <div className="collapse navbar-collapse mt-sm-0 mt-2 me-md-0 me-sm-4" id="navbar">
                <div className="ms-md-auto pe-md-3 d-flex align-items-center">
                    <div className="input-group">
                        <span className="input-group-text text-body" style={{backgroundColor:'#cb0c9f'}} onClick={handleSearch} ><i className="fas fa-search" aria-hidden="true" style={{color:'white'}}></i></span>
                        <input type="text" className="form-control" placeholder=" IMEI or Serial Number"  value={ searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}/>
                    </div>
                </div>
                <ul className="navbar-nav  justify-content-end">
                    <li className="nav-item d-flex align-items-center">
                        <Link className="nav-link text-body font-weight-bold px-5" onClick={() => handleLogoutWithConfirmation(handleLogout)}>
                            <i className="fas fa-sign-out-alt me-sm-1"></i>
                            <span className="d-sm-inline d-none">Sign Out</span>
                        </Link>
                    </li>
                    <li className="nav-item d-xl-none ps-3 d-flex align-items-center">
                        <Link href="#" className="nav-link text-body p-0" id="iconNavbarSidenav" onClick={(e) => { e.preventDefault(); toggleSidebar(); }}>
                            <div className="sidenav-toggler-inner">
                                <i className="sidenav-toggler-line"></i>
                                <i className="sidenav-toggler-line"></i>
                                <i className="sidenav-toggler-line"></i>
                            </div>
                        </Link>
                    </li>
                </ul>
            </div>
        </div>
    </nav>
    
  );
};

export default Header;
