// HeaderLogic.js
import { useState } from 'react';
import { showLogoutConfirmation, showLogoutSuccess } from './Alerts/alert';
import axios from 'axios';
import { useSearchResults } from './SearchResultsContext'; // Import custom hook

export const useHeaderLogic = (userInfo) => {
  const [isSidebarPinned, setSidebarPinned] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');

  const { updateSearchResults } = useSearchResults(); // Get the update function from context

  // Toggle sidebar pinning
  const toggleSidebar = () => {
    const body = document.body;
    if (isSidebarPinned) {
      body.classList.remove('g-sidenav-pinned');
    } else {
      body.classList.add('g-sidenav-pinned');
    }
    setSidebarPinned(!isSidebarPinned);
  };

  // Handle logout
  const handleLogoutWithConfirmation = (handleLogout) => {
    showLogoutConfirmation().then((result) => {
      if (result.isConfirmed) {
        handleLogout();
        showLogoutSuccess();
      }
    });
  };

  // Handle search
  const handleSearch = () => {
    if (searchTerm) {
      axios
        .get('/getPumpDetails', { params: { pump_id: searchTerm } })
        .then((response) => {
          // console.log('Full Response:', response);
  
          // Safely destructure status, message, and data from the response
          const { status, message, data = [] } = response.data.data || {};
  
          if (status === "Error") {
            // Display the error message directly from the response
            alert(message || `No data found for pump_id: ${searchTerm}`);
            console.warn("Error response detected:", { status, message, data });
            updateSearchResults({ status, data, message });
          } else if (status === "Success") {
            // console.log('Search results:', data);
            updateSearchResults({ status, data, message, userInfo });
          }
        })
        .catch((error) => {
          console.error("Error fetching pump data:", error);
  
          // Handle network or server errors with a fallback alert
          alert("Failed to fetch pump details. Please try again.");
          updateSearchResults({
            status: "Error",
            data: null,
            message: "Failed to fetch pump details due to a network error.",
          });
        });
    } else {
      alert("Please enter a valid search query.");
    }
  };

  return {
    toggleSidebar,
    handleLogoutWithConfirmation,
    handleSearch,
    searchTerm,
    setSearchTerm
  };
};
